  --danger: #ff5d5d;
  --good: #6ef0aa;
  --shadow: rgba(0,0,0,0.45);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle at center, #19273d 0%, #0b1119 40%, #02070d 100%);
  color: var(--text);
  font-family: Arial, Helvetica, sans-serif;
  overflow: hidden;
}

body {
  display: grid;
  place-items: center;
}

#game-shell {
  position: relative;
  width: min(100vw, 1280px);
  height: min(100vh, 720px);
  background: #000;
  border: 1px solid rgba(255,255,255,0.08);
  box-shadow: 0 0 40px rgba(0,0,0,0.6);
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  background: linear-gradient(#1e2b38, #0c0f14);
}

#hud {
  position: absolute;
  top: 18px;
  left: 18px;
  display: flex;
  gap: 12px;
  z-index: 8;
}

.panel {
  min-width: 110px;
  padding: 8px 12px;
  background: var(--panel);
  border: 1px solid var(--panel-border);
  border-radius: 10px;
  box-shadow: inset 0 0 8px rgba(255,255,255,0.05), var(--shadow);
  backdrop-filter: blur(6px);
}

.panel span {
  display: block;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.75);
  margin-bottom: 4px;
}

.panel strong {
  display: block;
  font-size: clamp(18px, 1.5vw, 28px);
  text-shadow: 0 0 14px rgba(255,255,255,0.2);
}

#messageBox {
  position: absolute;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%);
  padding: 12px 20px;
  border-radius: 12px;
  border: 1px solid var(--panel-border);
  background: rgba(6, 10, 15, 0.78);
  box-shadow: 0 10px 24px rgba(0,0,0,0.3);
  text-align: center;
  font-size: 18px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  opacity: 0;
  transition: opacity 0.2s ease;
  z-index: 9;
}

#messageBox.visible {
  opacity: 1;
}

#crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 30px;
  height: 30px;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 7;
}

#crosshair .line {
  position: absolute;
  display: block;
  background: rgba(255,255,255,0.85);
  box-shadow: 0 0 10px rgba(255,255,255,0.4);
}

#crosshair .horizontal {
  left: 50%;
  top: 50%;
  width: 18px;
  height: 2px;
  transform: translate(-50%, -50%);
}

#crosshair .vertical {
  left: 50%;
  top: 50%;
  width: 2px;
  height: 18px;
  transform: translate(-50%, -50%);
}

#touchControls {
  position: absolute;
  right: 18px;
  bottom: 18px;
  display: none;
  grid-template-columns: repeat(3, minmax(44px, 1fr));
  gap: 8px;
  width: min(42vw, 210px);
  z-index: 10;
}

#touchControls button {
  appearance: none;
  border: 1px solid rgba(255,255,255,0.2);
  background: rgba(17, 23, 31, 0.8);
  color: white;
  border-radius: 12px;
  font-size: 14px;
  padding: 14px 8px;
  font-weight: 700;
  touch-action: manipulation;
}

@media (pointer: coarse) and (hover: none) {
  #touchControls {
    display: grid;
  }
}

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const hud = {
  hp: document.getElementById('hpValue'),
  ammo: document.getElementById('ammoValue'),
  enemies: document.getElementById('enemyValue')
};
const messageBox = document.getElementById('messageBox');

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
const rand = (min, max) => Math.random() * (max - min) + min;
const dist = (ax, ay, bx, by) => Math.hypot(bx - ax, by - ay);

const state = {
  running: true,
  time: 0,
  wave: 1,
  score: 0,
  gameOver: false,
  levelCleared: false,
  messageTimeout: 0,
  keys: Object.create(null),
  mouse: { x: canvas.width / 2, y: canvas.height / 2, down: false },
  pointerLock: false,
  player: {
    x: 400,
    y: 300,
    radius: 18,
    hp: 100,
    speed: 220,
    ammo: 1,
    angle: 0,
    fireCooldown: 0,
    hitFlash: 0,
    weapon: 'handgun'
  },
  bullets: [],
  enemies: [],
  pickups: [],
  sparks: [],
  walls: [],
  goal: null,
  lastTimestamp: 0,
  pointerLookX: 0,
  pointerLookY: 0,
  touchFire: false,
  nextSpawn: 0,
  pickupsFound: 0
};

const arena = {
  w: 1400,
  h: 900,
  bounds: { x: 80, y: 80, w: 1240, h: 760 }
};

function createLevelWalls() {
  const walls = [
    { x: 0, y: 0, w: arena.w, h: 42 },
    { x: 0, y: 0, w: 42, h: arena.h },
    { x: arena.w - 42, y: 0, w: 42, h: arena.h },
    { x: 0, y: arena.h - 42, w: arena.w, h: 42 },
    { x: 220, y: 120, w: 220, h: 34 },
    { x: 470, y: 240, w: 140, h: 26 },
    { x: 760, y: 170, w: 120, h: 28 },
    { x: 980, y: 250, w: 180, h: 32 },
    { x: 850, y: 520, w: 180, h: 30 },
    { x: 520, y: 640, w: 200, h: 28 },
    { x: 180, y: 560, w: 150, h: 32 }
  ];
  return walls;
}

function resetGame() {
  state.time = 0;
  state.wave = 1;
  state.score = 0;
  state.gameOver = false;
  state.levelCleared = false;
  state.messageTimeout = 0;
  state.player.x = 140;
  state.player.y = 140;
  state.player.hp = 100;
  state.player.ammo = 1;
  state.player.fireCooldown = 0;
  state.player.hitFlash = 0;
  state.player.angle = 0;
  state.bullets = [];
  state.enemies = [];
  state.pickups = [];
  state.sparks = [];
  state.walls = createLevelWalls();
  state.goal = { x: 1160, y: 760, radius: 24, active: true };
  state.pickupsFound = 0;
  state.nextSpawn = 0;
  spawnPickup(200, 230);
  spawnPickup(920, 200);
  spawnPickup(600, 500);
  showMessage('Find your bullet and survive');
  updateHUD();
}

function showMessage(text, duration = 2200) {
  messageBox.textContent = text;
  messageBox.classList.add('visible');
  state.messageTimeout = duration;
}

function updateHUD() {
  hud.hp.textContent = String(Math.max(0, Math.ceil(state.player.hp)));
  hud.ammo.textContent = String(state.player.ammo);
  hud.enemies.textContent = String(state.enemies.length);
}

function spawnPickup(x, y) {
  state.pickups.push({ x, y, radius: 11, active: true, bob: Math.random() * Math.PI * 2 });
}

function addSparks(x, y, amount, color = '#ffd585') {
  for (let i = 0; i < amount; i += 1) {
    const angle = rand(0, Math.PI * 2);
    const speed = rand(20, 120);
    state.sparks.push({
      x,
      y,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      life: rand(0.25, 0.7),
      color
    });
  }
}

function spawnEnemy() {
  const margin = 60;
  let x = rand(margin, arena.w - margin);
  let y = rand(margin, arena.h - margin);
  let tries = 0;
  while (dist(x, y, state.player.x, state.player.y) < 220 && tries < 20) {
    x = rand(margin, arena.w - margin);
    y = rand(margin, arena.h - margin);
    tries += 1;
  }
  state.enemies.push({
    x,
    y,
    radius: 16,
    hp: 24 + state.wave * 4,
    speed: 46 + state.wave * 8,
    attackCooldown: rand(0.5, 1.2),
    color: '#ff5f5f'
  });
}

function fireBullet() {
  if (state.player.fireCooldown > 0 || state.gameOver) return;

  if (state.player.ammo <= 0) {
    showMessage('Out of ammo', 600);
    return;
  }

  const angle = state.player.angle;
  const muzzle = 22;
  const bulletSpeed = 540;
  state.bullets.push({
    x: state.player.x + Math.cos(angle) * muzzle,
    y: state.player.y + Math.sin(angle) * muzzle,
    vx: Math.cos(angle) * bulletSpeed,
    vy: Math.sin(angle) * bulletSpeed,
    life: 1.2,
    radius: 5,
    damage: 35
  });
  state.player.ammo -= 1;
  state.player.fireCooldown = 0.18;
  addSparks(state.player.x + Math.cos(angle) * muzzle, state.player.y + Math.sin(angle) * muzzle, 8, '#ffcc66');
  updateHUD();
}

function absorbBulletPickup() {
  const pickup = state.pickups.find(item => dist(item.x, item.y, state.player.x, state.player.y) < item.radius + state.player.radius + 8);
  if (!pickup) return false;
  if (pickup.x === 9999 && pickup.y === 9999) return false;
  pickup.active = false;
  state.player.ammo += 1;
  state.pickupsFound += 1;
  showMessage('Bullet recovered', 1000);
  updateHUD();
  return true;
}

function tryCollectGoal() {
  if (!state.goal || !state.goal.active) return;
  const d = dist(state.player.x, state.player.y, state.goal.x, state.goal.y);
  if (d < state.player.radius + state.goal.radius + 8) {
    if (state.player.ammo > 0) {
      state.levelCleared = true;
      state.running = false;
      showMessage('You survived the assault', 4000);
    } else {
      showMessage('Need the missing bullet', 1100);
    }
  }
}

function lineCircleIntersection(x1, y1, x2, y2, cx, cy, radius) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const a = dx * dx + dy * dy;
  const b = 2 * ((x1 - cx) * dx + (y1 - cy) * dy);
  const c = (x1 - cx) * (x1 - cx) + (y1 - cy) * (y1 - cy) - radius * radius;
  const disc = b * b - 4 * a * c;
  if (disc < 0) return false;
  const sqrtDisc = Math.sqrt(disc);
  const t1 = (-b - sqrtDisc) / (2 * a);
  const t2 = (-b + sqrtDisc) / (2 * a);
  return (t1 >= 0 && t1 <= 1) || (t2 >= 0 && t2 <= 1);
}

function collidesWithWall(x, y, radius) {
  for (const wall of state.walls) {
    const nearestX = clamp(x, wall.x, wall.x + wall.w);
    const nearestY = clamp(y, wall.y, wall.y + wall.h);
    const dx = x - nearestX;
    const dy = y - nearestY;
    if (dx * dx + dy * dy < radius * radius) return true;
  }
  return false;
}

function movePlayer(dt) {
  const player = state.player;
  let dx = 0;
  let dy = 0;
  if (state.keys.KeyW || state.keys.ArrowUp) dy -= 1;
  if (state.keys.KeyS || state.keys.ArrowDown) dy += 1;
  if (state.keys.KeyA || state.keys.ArrowLeft) dx -= 1;
  if (state.keys.KeyD || state.keys.ArrowRight) dx += 1;

  if (dx || dy) {
    const len = Math.hypot(dx, dy) || 1;
    dx /= len;
    dy /= len;
    const nextX = player.x + dx * player.speed * dt;
    const nextY = player.y + dy * player.speed * dt;
    if (!collidesWithWall(nextX, player.y, player.radius)) player.x = nextX;
    if (!collidesWithWall(player.x, nextY, player.radius)) player.y = nextY;
  }

  player.x = clamp(player.x, 40, arena.w - 40);
  player.y = clamp(player.y, 40, arena.h - 40);

  if (state.pointerLock) {
    const dxm = state.mouse.x - canvas.width / 2;
    const dym = state.mouse.y - canvas.height / 2;
    player.angle = Math.atan2(dym, dxm);
  }
}

function updateBullets(dt) {
  for (let i = state.bullets.length - 1; i >= 0; i -= 1) {
    const bullet = state.bullets[i];
    bullet.x += bullet.vx * dt;
    bullet.y += bullet.vy * dt;
    bullet.life -= dt;
    if (bullet.life <= 0) {
      state.bullets.splice(i, 1);
      continue;
    }
    if (bullet.x < 0 || bullet.x > arena.w || bullet.y < 0 || bullet.y > arena.h) {
      state.bullets.splice(i, 1);
      continue;
    }
    for (const wall of state.walls) {
      if (lineCircleIntersection(wall.x, wall.y, wall.x + wall.w, wall.y, bullet.x, bullet.y, bullet.radius) ||
          lineCircleIntersection(wall.x + wall.w, wall.y, wall.x + wall.w, wall.y + wall.h, bullet.x, bullet.y, bullet.radius) ||
          lineCircleIntersection(wall.x, wall.y + wall.h, wall.x + wall.w, wall.y + wall.h, bullet.x, bullet.y, bullet.radius) ||
          lineCircleIntersection(wall.x, wall.y, wall.x, wall.y + wall.h, bullet.x, bullet.y, bullet.radius)) {
        state.bullets.splice(i, 1);
        addSparks(bullet.x, bullet.y, 8, '#ffdb7a');
        break;
      }
    }
  }
}

function updateEnemies(dt) {
  for (let i = state.enemies.length - 1; i >= 0; i -= 1) {
    const enemy = state.enemies[i];
    const dx = state.player.x - enemy.x;
    const dy = state.player.y - enemy.y;
    const len = Math.hypot(dx, dy) || 1;
    const nx = dx / len;
    const ny = dy / len;
    const nextX = enemy.x + nx * enemy.speed * dt;
    const nextY = enemy.y + ny * enemy.speed * dt;
    if (!collidesWithWall(nextX, enemy.y, enemy.radius)) enemy.x = nextX;
    if (!collidesWithWall(enemy.x, nextY, enemy.radius)) enemy.y = nextY;

    if (dist(enemy.x, enemy.y, state.player.x, state.player.y) < enemy.radius + state.player.radius + 6) {
      state.player.hp -= 22 * dt;
      state.player.hitFlash = 0.25;
    }

    enemy.attackCooldown -= dt;
    if (enemy.attackCooldown <= 0) {
      const fireAngle = Math.atan2(state.player.y - enemy.y, state.player.x - enemy.x);
      state.bullets.push({
        x: enemy.x + Math.cos(fireAngle) * 18,
        y: enemy.y + Math.sin(fireAngle) * 18,
        vx: Math.cos(fireAngle) * 260,
        vy: Math.sin(fireAngle) * 260,
        life: 2.3,
        radius: 6,
        damage: 24,
        enemy: true
      });
      enemy.attackCooldown = rand(1.3, 2.4);
    }

    for (let j = state.bullets.length - 1; j >= 0; j -= 1) {
      const bullet = state.bullets[j];
      if (bullet.enemy) continue;
      if (dist(bullet.x, bullet.y, enemy.x, enemy.y) < bullet.radius + enemy.radius) {
        enemy.hp -= bullet.damage;
        state.bullets.splice(j, 1);
        addSparks(bullet.x, bullet.y, 12, '#ffe493');
        if (enemy.hp <= 0) {
          state.enemies.splice(i, 1);
          state.score += 10;
          addSparks(enemy.x, enemy.y, 20, '#ff8a65');
          if (Math.random() < 0.35) {
            spawnPickup(enemy.x, enemy.y);
          }
          break;
        }
      }
    }
  }

  if (state.player.hp <= 0) {
    state.player.hp = 0;
    state.gameOver = true;
    state.running = false;
    showMessage('You were overrun', 4000);
  }
}

function updatePickups(dt) {
  for (let i = state.pickups.length - 1; i >= 0; i -= 1) {
    const item = state.pickups[i];
    if (!item.active) {
      state.pickups.splice(i, 1);
      continue;
    }
    item.bob += dt * 2.8;
    if (dist(item.x, item.y, state.player.x, state.player.y) < item.radius + state.player.radius + 8) {
      if (state.player.ammo <= 0) {
        state.player.ammo = 1;
        state.pickupsFound += 1;
        item.active = false;
        showMessage('Bullet restored', 1000);
        updateHUD();
      }
    }
  }
}

function updateGoal() {
  if (!state.goal) return;
  const d = dist(state.player.x, state.player.y, state.goal.x, state.goal.y);
  if (d < 90) {
    state.goal.active = true;
  }
}

function update(dt) {
  if (!state.running) {
    if (state.messageTimeout > 0) {
      state.messageTimeout -= dt * 1000;
      if (state.messageTimeout <= 0) messageBox.classList.remove('visible');
    }
    return;
  }

  state.time += dt;
  state.player.fireCooldown = Math.max(0, state.player.fireCooldown - dt);
  state.player.hitFlash = Math.max(0, state.player.hitFlash - dt);

  movePlayer(dt);
  updateBullets(dt);
  updateEnemies(dt);
  updatePickups(dt);
  updateGoal();
  tryCollectGoal();
  absorbBulletPickup();

  if (state.player.ammo <= 0) {
    const bullet = state.pickups.find(item => item.active && dist(item.x, item.y, state.player.x, state.player.y) < 140);
    if (bullet) {
      showMessage('Recover the bullet', 600); 
    }
  }

  if (state.time > state.nextSpawn) {
    state.nextSpawn = state.time + Math.max(0.8, 3.2 - state.wave * 0.2);
    spawnEnemy();
    state.wave += 1;
  }

  if (state.player.hp <= 0) {
    state.gameOver = true;
    state.running = false;
  }

  if (messageBox.classList.contains('visible')) {
    state.messageTimeout -= dt * 1000;
    if (state.messageTimeout <= 0) messageBox.classList.remove('visible');
  }

  updateHUD();
}

function drawBackground() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  const grad = ctx.createRadialGradient(canvas.width / 2, canvas.height / 2, 30, canvas.width / 2, canvas.height / 2, canvas.width * 0.9);
  grad.addColorStop(0, '#27384d');
  grad.addColorStop(1, '#070d16');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.save();
  ctx.translate(-state.player.x + canvas.width / 2, -state.player.y + canvas.height / 2);

  ctx.fillStyle = '#1a2b39';
  ctx.fillRect(0, 0, arena.w, arena.h);

  ctx.strokeStyle = '#385161';
  ctx.lineWidth = 2;
  for (let x = 0; x <= arena.w; x += 60) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, arena.h);
    ctx.stroke();
  }
  for (let y = 0; y <= arena.h; y += 60) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(arena.w, y);
    ctx.stroke();
  }

  for (const wall of state.walls) {
    ctx.fillStyle = '#6f7f90';
    ctx.fillRect(wall.x, wall.y, wall.w, wall.h);
  }

  for (const pickup of state.pickups) {
    if (!pickup.active) continue;
    const pulse = 1 + Math.sin(pickup.bob) * 0.22;
    ctx.save();
    ctx.translate(pickup.x, pickup.y);
    ctx.fillStyle = '#ffd166';
    ctx.beginPath();
    ctx.arc(0, 0, pickup.radius * pulse, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#1d1d1d';
    ctx.fillRect(-2, -12, 4, 24);
    ctx.restore();
  }

  for (const bullet of state.bullets) {
    ctx.fillStyle = bullet.enemy ? '#ff7a59' : '#ffd166';
    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, bullet.radius, 0, Math.PI * 2);
    ctx.fill();
  }

  for (const enemy of state.enemies) {
    ctx.fillStyle = enemy.color;
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#2d0c0c';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(enemy.x, enemy.y);
    ctx.lineTo(enemy.x + Math.cos(Math.atan2(state.player.y - enemy.y, state.player.x - enemy.x)) * 18, enemy.y + Math.sin(Math.atan2(state.player.y - enemy.y, state.player.x - enemy.x)) * 18);
    ctx.stroke();
  }

  ctx.fillStyle = '#bdf5ff';
  ctx.beginPath();
  ctx.arc(state.player.x, state.player.y, state.player.radius, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = '#7ed1ff';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(state.player.x, state.player.y);
  ctx.lineTo(state.player.x + Math.cos(state.player.angle) * 22, state.player.y + Math.sin(state.player.angle) * 22);
  ctx.stroke();

  if (state.goal && state.goal.active) {
    ctx.fillStyle = '#65f5b4';
    ctx.beginPath();
    ctx.arc(state.goal.x, state.goal.y, state.goal.radius, 0, Math.PI * 2);
    ctx.fill();
  }

  for (const spark of state.sparks) {
    ctx.fillStyle = spark.color;
    ctx.globalAlpha = spark.life;
    ctx.fillRect(spark.x, spark.y, 4, 4);
    ctx.globalAlpha = 1;
  }

  ctx.restore();

  if (state.player.hitFlash > 0) {
    ctx.fillStyle = `rgba(255, 80, 80, ${state.player.hitFlash * 0.75})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
}

function drawStatus() {
  ctx.fillStyle = 'rgba(5,10,15,0.55)';
  ctx.fillRect(18, canvas.height - 70, 260, 52);
  ctx.fillStyle = '#ecf3ff';
  ctx.font = '18px sans-serif';
  ctx.fillText('Wave ' + state.wave, 32, canvas.height - 38);
  ctx.fillText('Score ' + state.score, 140, canvas.height - 38);

  if (state.gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 44px sans-serif';
    ctx.fillText('Game Over', canvas.width / 2 - 130, canvas.height / 2 - 10);
    ctx.font = '20px sans-serif';
    ctx.fillText('Press R to restart', canvas.width / 2 - 95, canvas.height / 2 + 30);
  }

  if (state.levelCleared) {
    ctx.fillStyle = 'rgba(0,0,0,0.55)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#b8ffd7';
    ctx.font = 'bold 42px sans-serif';
    ctx.fillText('Area Secured', canvas.width / 2 - 170, canvas.height / 2 - 12);
    ctx.font = '20px sans-serif';
    ctx.fillText('Press R to return to the fight', canvas.width / 2 - 160, canvas.height / 2 + 28);
  }
}

function render() {
  drawBackground();
  drawStatus();
}

let lastFrame = 0;
function frame(timestamp) {
  const dt = Math.min(0.033, (timestamp - lastFrame) / 1000 || 0.016);
  lastFrame = timestamp;
  update(dt);
  render();
  requestAnimationFrame(frame);
}

function handlePointerMove(event) {
  const rect = canvas.getBoundingClientRect();
  const scaleX = canvas.width / rect.width;
  const scaleY = canvas.height / rect.height;
  const x = (event.clientX - rect.left) * scaleX;
  const y = (event.clientY - rect.top) * scaleY;
  const centerX = canvas.width / 2;
  const centerY = canvas.height / 2;
  const dx = x - centerX;
  const dy = y - centerY;
  state.player.angle = Math.atan2(dy, dx);
  state.mouse.x = x;
  state.mouse.y = y;
}

function updateKeyBindings() {
  const activeKeys = state.keys;
  if (activeKeys.KeyE) {
    absorbBulletPickup();
  }
  if (activeKeys.Space) {
    fireBullet();
  }
  if (activeKeys.KeyR) {
    resetGame();
    activeKeys.KeyR = false;
  }
}

function bindTouchControls() {
  const buttons = document.querySelectorAll('#touchControls button');
  buttons.forEach(button => {
    const key = button.dataset.key;
    const press = (e) => {
      e.preventDefault();
      state.keys[key] = true;
      if (key === 'Space') state.touchFire = true;
    };
    const release = () => {
      delete state.keys[key];
      if (key === 'Space') state.touchFire = false;
    };
    button.addEventListener('pointerdown', press);
    button.addEventListener('pointerup', release);
    button.addEventListener('pointerleave', release);
    button.addEventListener('pointercancel', release);
  });
}

window.addEventListener('keydown', (event) => {
  if (event.code === 'KeyR') {
    resetGame();
    return;
  }
  if (event.code === 'KeyE') {
    state.keys[event.code] = true;
    absorbBulletPickup();
    return;
  }
  if (event.code === 'Space') {
    state.keys[event.code] = true;
    fireBullet();
    return;
  }
  state.keys[event.code] = true;
});

window.addEventListener('keyup', (event) => {
  delete state.keys[event.code];
});

canvas.addEventListener('pointerdown', (event) => {
  if (event.button === 0) {
    state.mouse.down = true;
    fireBullet();
  }
  canvas.setPointerCapture(event.pointerId);
});

canvas.addEventListener('pointermove', handlePointerMove);
canvas.addEventListener('pointerup', () => { state.mouse.down = false; });
canvas.addEventListener('click', () => {
  if (document.pointerLockElement !== canvas) {
    canvas.requestPointerLock();
  }
});

window.addEventListener('pointerlockchange', () => {
  state.pointerLock = document.pointerLockElement === canvas;
});

resetGame();
bindTouchControls();
requestAnimationFrame(frame);
setInterval(updateKeyBindings, 16);

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const hpEl = document.getElementById('hpValue');
const ammoEl = document.getElementById('ammoValue');
const enemiesEl = document.getElementById('enemyValue');
const messageBox = document.getElementById('messageBox');

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
const rand = (min, max) => Math.random() * (max - min) + min;
const dist = (ax, ay, bx, by) => Math.hypot(bx - ax, by - ay);
const normalizeAngle = (angle) => {
  while (angle < -Math.PI) angle += Math.PI * 2;
  while (angle > Math.PI) angle -= Math.PI * 2;
  return angle;
};

const FOV = Math.PI / 3;
const MAX_DEPTH = 24;
const MAP_COLS = 16;
const MAP_ROWS = 16;

const state = {
  time: 0,
  running: true,
  won: false,
  gameOver: false,
  messageTimer: 0,
  keys: Object.create(null),
  pointerLock: false,
  player: {
    x: 1.5,
    y: 1.5,
    radius: 0.22,
    hp: 100,
    ammo: 0,
    angle: 0,
    fireCooldown: 0,
    flash: 0,
    dodge: 0
  },
  bullets: [],
  enemyBullets: [],
  enemies: [],
  particles: [],
  pickup: null,
  exit: null,
  map: null,
  mouse: { x: canvas.width / 2, y: canvas.height / 2 }
};

function setMessage(text, duration = 1800) {
  messageBox.textContent = text;
  messageBox.classList.add('visible');
  state.messageTimer = duration;
}

function buildMap() {
  const map = Array.from({ length: MAP_ROWS }, () => Array(MAP_COLS).fill(1));

  for (let y = 1; y < MAP_ROWS - 1; y += 1) {
    for (let x = 1; x < MAP_COLS - 1; x += 1) {
      if (x % 2 === 1 && y % 2 === 1) {
        map[y][x] = 0;
      } else if (x > 1 && x < MAP_COLS - 2 && y > 1 && y < MAP_ROWS - 2 && (x + y) % 4 !== 0) {
        map[y][x] = 0;
      }
    }
  }

  for (let i = 0; i < 6; i += 1) {
    const wx = 2 + (i * 2) % 10;
    const wy = 2 + (i * 3) % 10;
    map[wy][wx] = 1;
  }

  map[1][1] = 0;
  map[1][2] = 0;
  map[2][1] = 0;

  return map;
}

function resetGame() {
  state.map = buildMap();
  state.running = true;
  state.won = false;
  state.gameOver = false;
  state.player.x = 1.5;
  state.player.y = 1.5;
  state.player.hp = 100;
  state.player.angle = 0;
  state.player.ammo = 0;
  state.player.fireCooldown = 0;
  state.player.flash = 0;
  state.bullets = [];
  state.enemyBullets = [];
  state.particles = [];
  state.enemies = [
    { x: 5.5, y: 5.5, hp: 35, speed: 1.15, radius: 0.28, attackCooldown: 1.0 },
    { x: 11.5, y: 5.5, hp: 40, speed: 1.2, radius: 0.28, attackCooldown: 0.7 },
    { x: 9.5, y: 10.5, hp: 50, speed: 1.1, radius: 0.3, attackCooldown: 1.2 },
    { x: 12.5, y: 12.5, hp: 45, speed: 1.25, radius: 0.3, attackCooldown: 0.9 }
  ];
  state.pickup = { x: 13.5, y: 12.5, radius: 0.24, collected: false };
  state.exit = { x: 13.5, y: 2.5, radius: 0.4, unlocked: false };
  setMessage('Find the lost bullet', 2000);
  updateHud();
}

function updateHud() {
  hpEl.textContent = String(Math.max(0, Math.ceil(state.player.hp)));
  ammoEl.textContent = String(state.player.ammo);
  enemiesEl.textContent = String(state.enemies.length);
}

function isWall(x, y) {
  const cellX = Math.floor(x);
  const cellY = Math.floor(y);
  if (cellX < 0 || cellY < 0 || cellX >= MAP_COLS || cellY >= MAP_ROWS) return true;
  return state.map[cellY][cellX] === 1;
}

function canMoveTo(x, y, radius = 0.25) {
  const checks = [
    [x - radius, y - radius],
    [x + radius, y - radius],
    [x - radius, y + radius],
    [x + radius, y + radius]
  ];
  return !checks.some(([cx, cy]) => isWall(cx, cy));
}

function castRay(angle) {
  let distance = 0;
  while (distance < MAX_DEPTH) {
    const x = state.player.x + Math.cos(angle) * distance;
    const y = state.player.y + Math.sin(angle) * distance;
    if (isWall(x, y)) {
      return { distance, x, y };
    }
    distance += 0.04;
  }
  return { distance: MAX_DEPTH, x: state.player.x + Math.cos(angle) * MAX_DEPTH, y: state.player.y + Math.sin(angle) * MAX_DEPTH };
}

function addParticles(x, y, count, color = '#ffd166') {
  for (let i = 0; i < count; i += 1) {
    state.particles.push({
      x,
      y,
      vx: rand(-1.2, 1.2),
      vy: rand(-1.2, 1.2),
      life: rand(0.2, 0.8),
      color
    });
  }
}

function fireBullet() {
  if (!state.running || state.player.fireCooldown > 0) return;
  if (state.player.ammo <= 0) {
    setMessage('No bullets left', 750);
    return;
  }

  const shotAngle = state.player.angle;
  state.bullets.push({
    x: state.player.x + Math.cos(shotAngle) * 0.5,
    y: state.player.y + Math.sin(shotAngle) * 0.5,
    vx: Math.cos(shotAngle) * 7.5,
    vy: Math.sin(shotAngle) * 7.5,
    life: 0.9,
    radius: 0.09,
    damage: 35
  });
  state.player.ammo -= 1;
  state.player.fireCooldown = 0.18;
  addParticles(state.player.x + Math.cos(shotAngle) * 0.6, state.player.y + Math.sin(shotAngle) * 0.6, 6, '#ffd166');
  updateHud();
}

function damagePlayer(amount) {
  state.player.hp = Math.max(0, state.player.hp - amount);
  state.player.flash = 0.32;
  if (state.player.hp <= 0) {
    state.player.hp = 0;
    state.gameOver = true;
    state.running = false;
    setMessage('You were overrun', 3000);
  }
}

function updatePlayer(dt) {
  const player = state.player;
  const forward = (state.keys.KeyW || state.keys.ArrowUp ? 1 : 0) - (state.keys.KeyS || state.keys.ArrowDown ? 1 : 0);
  const strafe = (state.keys.KeyD || state.keys.ArrowRight ? 1 : 0) - (state.keys.KeyA || state.keys.ArrowLeft ? 1 : 0);

  let moveX = 0;
  let moveY = 0;

  if (forward !== 0 || strafe !== 0) {
    const len = Math.hypot(forward, strafe) || 1;
    const nx = (Math.cos(player.angle) * forward + Math.cos(player.angle + Math.PI / 2) * strafe) / len;
    const ny = (Math.sin(player.angle) * forward + Math.sin(player.angle + Math.PI / 2) * strafe) / len;
    moveX = nx * 2.4 * dt;
    moveY = ny * 2.4 * dt;
  }

  const nextX = player.x + moveX;
  const nextY = player.y + moveY;
  if (canMoveTo(nextX, player.y, player.radius)) player.x = nextX;
  if (canMoveTo(player.x, nextY, player.radius)) player.y = nextY;

  player.fireCooldown = Math.max(0, player.fireCooldown - dt);
  player.flash = Math.max(0, player.flash - dt);

  if (state.pointerLock) {
    const dx = state.mouse.x - canvas.width / 2;
    const dy = state.mouse.y - canvas.height / 2;
    player.angle = Math.atan2(dy, dx);
  }
}

function updateBullets(dt) {
  for (let i = state.bullets.length - 1; i >= 0; i -= 1) {
    const bullet = state.bullets[i];
    bullet.x += bullet.vx * dt;
    bullet.y += bullet.vy * dt;
    bullet.life -= dt;

    if (bullet.life <= 0 || isWall(bullet.x, bullet.y)) {
      addParticles(bullet.x, bullet.y, 5, '#ffce66');
      state.bullets.splice(i, 1);
      continue;
    }

    for (let j = state.enemies.length - 1; j >= 0; j -= 1) {
      const enemy = state.enemies[j];
      if (dist(bullet.x, bullet.y, enemy.x, enemy.y) <= bullet.radius + enemy.radius) {
        enemy.hp -= bullet.damage;
        addParticles(bullet.x, bullet.y, 12, '#ffcf7a');
        state.bullets.splice(i, 1);
        if (enemy.hp <= 0) {
          state.enemies.splice(j, 1);
          addParticles(enemy.x, enemy.y, 22, '#ff8c69');
        }
        break;
      }
    }
  }

  for (let i = state.enemyBullets.length - 1; i >= 0; i -= 1) {
    const bullet = state.enemyBullets[i];
    bullet.x += bullet.vx * dt;
    bullet.y += bullet.vy * dt;
    bullet.life -= dt;

    if (bullet.life <= 0 || isWall(bullet.x, bullet.y)) {
      state.enemyBullets.splice(i, 1);
      continue;
    }

    if (dist(bullet.x, bullet.y, state.player.x, state.player.y) <= 0.25 + bullet.radius) {
      damagePlayer(bullet.damage);
      state.enemyBullets.splice(i, 1);
    }
  }
}

function updateEnemies(dt) {
  for (const enemy of state.enemies) {
    const dx = state.player.x - enemy.x;
    const dy = state.player.y - enemy.y;
    const d = Math.hypot(dx, dy) || 1;
    enemy.attackCooldown -= dt;

    if (d > 0.8) {
      const stepX = (dx / d) * enemy.speed * dt;
      const stepY = (dy / d) * enemy.speed * dt;
      const testX = enemy.x + stepX;
      const testY = enemy.y + stepY;
      if (canMoveTo(testX, enemy.y, enemy.radius)) enemy.x = testX;
      if (canMoveTo(enemy.x, testY, enemy.radius)) enemy.y = testY;
    }

    if (d < 5.2 && enemy.attackCooldown <= 0) {
      const angle = Math.atan2(dy, dx);
      state.enemyBullets.push({
        x: enemy.x + Math.cos(angle) * 0.35,
        y: enemy.y + Math.sin(angle) * 0.35,
        vx: Math.cos(angle) * 4.0,
        vy: Math.sin(angle) * 4.0,
        life: 2.5,
        radius: 0.09,
        damage: 12
      });
      enemy.attackCooldown = rand(1.1, 1.8);
    }

    if (d < 0.5 + enemy.radius + state.player.radius) {
      damagePlayer(18 * dt);
    }
  }
}

function updatePickup() {
  if (!state.pickup || state.pickup.collected) return;
  if (dist(state.player.x, state.player.y, state.pickup.x, state.pickup.y) < 0.5) {
    state.player.ammo = 1;
    state.pickup.collected = true;
    state.exit.unlocked = true;
    setMessage('Bullet recovered', 1600);
    updateHud();
  }
}

function updateExit() {
  if (!state.exit || !state.exit.unlocked) return;
  if (dist(state.player.x, state.player.y, state.exit.x, state.exit.y) < 0.6) {
    state.won = true;
    state.running = false;
    setMessage('Escape successful', 3200);
  }
}

function updateParticles(dt) {
  for (let i = state.particles.length - 1; i >= 0; i -= 1) {
    const particle = state.particles[i];
    particle.x += particle.vx * dt;
    particle.y += particle.vy * dt;
    particle.life -= dt;
    if (particle.life <= 0) state.particles.splice(i, 1);
  }
}

function update(dt) {
  if (!state.running) {
    if (state.messageTimer > 0) {
      state.messageTimer -= dt * 1000;
      if (state.messageTimer <= 0) messageBox.classList.remove('visible');
    }
    return;
  }

  state.time += dt;
  updatePlayer(dt);
  updateBullets(dt);
  updateEnemies(dt);
  updateParticles(dt);
  updatePickup();
  updateExit();

  if (!state.pickup.collected && dist(state.player.x, state.player.y, state.pickup.x, state.pickup.y) < 3.5) {
    setMessage('Recover the bullet', 500);
  }

  if (state.player.hp <= 0) {
    state.gameOver = true;
    state.running = false;
  }

  if (state.messageTimer > 0) {
    state.messageTimer -= dt * 1000;
    if (state.messageTimer <= 0) messageBox.classList.remove('visible');
  }

  updateHud();
}

function drawBackground() {
  const sky = ctx.createLinearGradient(0, 0, 0, canvas.height / 2);
  sky.addColorStop(0, '#657d8f');
  sky.addColorStop(1, '#1d2c3d');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, canvas.width, canvas.height / 2);

  const floor = ctx.createLinearGradient(0, canvas.height / 2, 0, canvas.height);
  floor.addColorStop(0, '#1d1e22');
  floor.addColorStop(1, '#090b0e');
  ctx.fillStyle = floor;
  ctx.fillRect(0, canvas.height / 2, canvas.width, canvas.height / 2);
}

function drawWalls() {
  const depthBuffer = new Array(canvas.width);
  for (let column = 0; column < canvas.width; column += 2) {
    const rayAngle = state.player.angle - FOV / 2 + (column / canvas.width) * FOV;
    const hit = castRay(rayAngle);
    depthBuffer[column] = hit.distance;

    const corrected = hit.distance * Math.cos(rayAngle - state.player.angle);
    const wallHeight = clamp((canvas.height / corrected) * 0.8, 0, canvas.height * 0.9);
    const top = (canvas.height - wallHeight) / 2;
    const shade = clamp(255 - hit.distance * 18, 40, 220);

    ctx.fillStyle = `rgb(${shade}, ${shade * 0.9}, ${shade * 0.75})`;
    ctx.fillRect(column, top, 2, wallHeight);
  }
  return depthBuffer;
}

function drawSprite(sprite, color, size, distance, angle) {
  const screenX = canvas.width / 2 + Math.tan(angle) * (canvas.width / (2 * Math.tan(FOV / 2)));
  const screenY = canvas.height / 2;
  const spriteSize = clamp((canvas.height / distance) * size, 8, canvas.height * 0.75);
  const half = spriteSize / 2;

  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.arc(screenX, screenY, half, 0, Math.PI * 2);
  ctx.fill();
}

function drawSprites(depthBuffer) {
  const sprites = [];

  for (const enemy of state.enemies) {
    const dx = enemy.x - state.player.x;
    const dy = enemy.y - state.player.y;
    const distance = Math.hypot(dx, dy);
    const angle = Math.atan2(dy, dx) - state.player.angle;
    const normalized = normalizeAngle(angle);
    if (Math.abs(normalized) < FOV + 0.6 && distance > 0.2) {
      sprites.push({ type: 'enemy', x: enemy.x, y: enemy.y, distance, angle: normalized, radius: 0.3, color: '#ff6b5f' });
    }
  }

  if (!state.pickup.collected) {
    const dx = state.pickup.x - state.player.x;
    const dy = state.pickup.y - state.player.y;
    const distance = Math.hypot(dx, dy);
    const angle = normalizeAngle(Math.atan2(dy, dx) - state.player.angle);
    if (Math.abs(angle) < FOV + 0.6 && distance > 0.2) {
      sprites.push({ type: 'pickup', x: state.pickup.x, y: state.pickup.y, distance, angle, radius: 0.25, color: '#ffe16b' });
    }
  }

  if (state.exit.unlocked) {
    const dx = state.exit.x - state.player.x;
    const dy = state.exit.y - state.player.y;
    const distance = Math.hypot(dx, dy);
    const angle = normalizeAngle(Math.atan2(dy, dx) - state.player.angle);
    if (Math.abs(angle) < FOV + 0.6 && distance > 0.2) {
      sprites.push({ type: 'exit', x: state.exit.x, y: state.exit.y, distance, angle, radius: 0.4, color: '#6df7b2' });
    }
  }

  sprites.sort((a, b) => b.distance - a.distance);

  for (const sprite of sprites) {
    const screenX = canvas.width / 2 + Math.tan(sprite.angle) * (canvas.width / (2 * Math.tan(FOV / 2)));
    const spriteSize = clamp((canvas.height / sprite.distance) * 0.8, 14, 220);
    const centerX = screenX;
    const centerY = canvas.height / 2;
    const xStart = centerX - spriteSize / 2;
    const xEnd = centerX + spriteSize / 2;
    const inFront = sprite.distance < depthBuffer[Math.min(canvas.width - 1, Math.max(0, Math.round(centerX)))];

    if (!inFront) continue;

    if (sprite.type === 'enemy') {
      ctx.fillStyle = sprite.color;
      ctx.beginPath();
      ctx.arc(centerX, centerY, spriteSize / 2, 0, Math.PI * 2);
      ctx.fill();
    }

    if (sprite.type === 'pickup') {
      ctx.fillStyle = '#ffe16b';
      ctx.beginPath();
      ctx.arc(centerX, centerY, spriteSize / 2, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#111';
      ctx.fillRect(centerX - 3, centerY - spriteSize * 0.65, 6, spriteSize * 1.3);
    }

    if (sprite.type === 'exit') {
      ctx.fillStyle = '#73f6bd';
      ctx.beginPath();
      ctx.arc(centerX, centerY, spriteSize / 2, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#c0ffe4';
      ctx.lineWidth = 3;
      ctx.strokeRect(centerX - spriteSize * 0.35, centerY - spriteSize * 0.35, spriteSize * 0.7, spriteSize * 0.7);
    }
  }
}

function drawParticles() {
  for (const particle of state.particles) {
    ctx.fillStyle = particle.color;
    ctx.globalAlpha = particle.life * 1.4;
    ctx.fillRect(
      canvas.width / 2 + (particle.x - state.player.x) * 70,
      canvas.height / 2 + (particle.y - state.player.y) * 70,
      4,
      4
    );
    ctx.globalAlpha = 1;
  }
}

function drawGun() {
  const x = canvas.width / 2;
  const y = canvas.height - 60;
  ctx.fillStyle = '#111';
  ctx.fillRect(x - 42, y - 12, 84, 42);
  ctx.fillStyle = '#222';
  ctx.fillRect(x - 16, y - 48, 32, 56);
  ctx.fillStyle = '#8b9197';
  ctx.fillRect(x - 6, y - 88, 12, 42);
}

function drawHud() {
  ctx.fillStyle = 'rgba(10, 14, 20, 0.5)';
  ctx.fillRect(18, 18, 220, 110);
  ctx.fillStyle = '#edf5ff';
  ctx.font = 'bold 20px sans-serif';
  ctx.fillText('HP', 30, 46);
  ctx.fillText(String(Math.max(0, Math.ceil(state.player.hp)), 180, 46));
  ctx.fillText('AMMO', 30, 78);
  ctx.fillText(String(state.player.ammo), 180, 78);
  ctx.fillText('THREAT', 30, 110);
  ctx.fillText(String(state.enemies.length), 180, 110);

  if (!state.exit.unlocked) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(canvas.width - 270, 18, 250, 64);
    ctx.fillStyle = '#ffd166';
    ctx.font = 'bold 18px sans-serif';
    ctx.fillText('Objective: find bullet', canvas.width - 250, 52);
  } else {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(canvas.width - 260, 18, 240, 64);
    ctx.fillStyle = '#7df7c7';
    ctx.font = 'bold 18px sans-serif';
    ctx.fillText('Objective: escape', canvas.width - 240, 52);
  }

  if (state.gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 44px sans-serif';
    ctx.fillText('Game Over', canvas.width / 2 - 120, canvas.height / 2 - 12);
    ctx.font = '22px sans-serif';
    ctx.fillText('Press R to restart', canvas.width / 2 - 110, canvas.height / 2 + 32);
  }

  if (state.won) {
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#9dffd2';
    ctx.font = 'bold 44px sans-serif';
    ctx.fillText('Area Secured', canvas.width / 2 - 170, canvas.height / 2 - 12);
    ctx.font = '22px sans-serif';
    ctx.fillText('Press R to restart', canvas.width / 2 - 110, canvas.height / 2 + 32);
  }
}

function render() {
  drawBackground();
  const depthBuffer = drawWalls();
  drawSprites(depthBuffer);
  drawParticles();
  drawGun();
  drawHud();

  if (state.player.flash > 0) {
    ctx.fillStyle = `rgba(255, 79, 79, ${state.player.flash * 0.8})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
}

let lastFrame = 0;
function frame(timestamp) {
  const dt = Math.min(0.033, (timestamp - lastFrame) / 1000 || 0.016);
  lastFrame = timestamp;
  update(dt);
  render();
  requestAnimationFrame(frame);
}

function handlePointerMove(event) {
  const rect = canvas.getBoundingClientRect();
  const x = (event.clientX - rect.left) / rect.width;
  const y = (event.clientY - rect.top) / rect.height;
  state.mouse.x = x * canvas.width;
  state.mouse.y = y * canvas.height;
  if (document.pointerLockElement === canvas) {
    const dx = state.mouse.x - canvas.width / 2;
    const dy = state.mouse.y - canvas.height / 2;
    state.player.angle = Math.atan2(dy, dx);
  }
}

window.addEventListener('keydown', (event) => {
  if (event.code === 'KeyR') {
    resetGame();
    return;
  }
  if (event.code === 'Space') {
    event.preventDefault();
    fireBullet();
    return;
  }
  if (event.code === 'KeyE') {
    updatePickup();
    return;
  }
  state.keys[event.code] = true;
});

window.addEventListener('keyup', (event) => {
  delete state.keys[event.code];
});

canvas.addEventListener('pointerdown', (event) => {
  if (event.button === 0) {
    fireBullet();
    canvas.requestPointerLock();
  }
});

canvas.addEventListener('pointermove', handlePointerMove);
canvas.addEventListener('click', () => {
  if (document.pointerLockElement !== canvas) canvas.requestPointerLock();
});
window.addEventListener('pointerlockchange', () => {
  state.pointerLock = document.pointerLockElement === canvas;
});

const touchButtons = document.querySelectorAll('#touchControls button');
touchButtons.forEach((button) => {
  const code = button.dataset.key;
  const press = (event) => {
    event.preventDefault();
    state.keys[code] = true;
    if (code === 'Space') fireBullet();
  };
  const release = () => {
    delete state.keys[code];
  };
  button.addEventListener('pointerdown', press);
  button.addEventListener('pointerup', release);
  button.addEventListener('pointerleave', release);
  button.addEventListener('pointercancel', release);
});

resetGame();
requestAnimationFrame(frame);

