function buildMap() {
  const map = Array.from({ length: MAP_ROWS }, () => Array(MAP_COLS).fill(1));

  for (let y = 1; y < MAP_ROWS - 1; y += 1) {
    for (let x = 1; x < MAP_COLS - 1; x += 1) {
      if (x % 2 === 1 && y % 2 === 1) {
        map[y][x] = 0;
      } else if (x > 1 && x < MAP_COLS - 2 && y > 1 && y < MAP_ROWS - 2 && (x + y) % 4 !== 0) {
        map[y][x] = 0;
      }
    }
  }

  for (let i = 0; i < 6; i += 1) {
    const wx = 2 + (i * 2) % 10;
    const wy = 2 + (i * 3) % 10;
    map[wy][wx] = 1;
  }

  map[1][1] = 0;
  map[1][2] = 0;
  map[2][1] = 0;

  return map;
}

